<div id="wrap"><canvas id="cv" width="960" height="600"></canvas></div>
<script>
"use strict";
/* ============================================================
   Balloon Bow — a Win95-flavored archery level
   - Aim with mouse, hold LMB to draw (power), release to shoot
   - Pop balloons for points; 3 misses = lose
   - All sound synthesized with WebAudio (no assets)
   ============================================================ */

const cv = document.getElementById('cv');
const ctx = cv.getContext('2d');
const W = cv.width, H = cv.height;

/* ---------- tiny helpers ---------- */
const rand = (a, b) => a + Math.random() * (b - a);
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const TAU = Math.PI * 2;

/* ---------- audio (synth, lazy init on first gesture) ---------- */
let AC = null, master = null;
function audio() {
  if (AC) return AC;
  AC = new (window.AudioContext || window.webkitAudioContext)();
  master = AC.createGain();
  master.gain.value = 0.5;
  master.connect(AC.destination);
  return AC;
}
function resumeAudio() { const a = audio(); if (a.state === 'suspended') a.resume(); }

function tone({ f0 = 440, f1 = f0, dur = 0.15, type = 'sine', vol = 0.3, delay = 0, curve = 'exp' }) {
  const a = audio();
  const t = a.currentTime + delay;
  const o = a.createOscillator(), g = a.createGain();
  o.type = type;
  o.frequency.setValueAtTime(f0, t);
  if (f1 !== f0) {
    if (curve === 'exp') o.frequency.exponentialRampToValueAtTime(Math.max(1, f1), t + dur);
    else o.frequency.linearRampToValueAtTime(f1, t + dur);
  }
  g.gain.setValueAtTime(vol, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  o.connect(g); g.connect(master);
  o.start(t); o.stop(t + dur + 0.02);
}
function noise({ dur = 0.2, vol = 0.3, f = 1000, q = 1, delay = 0, sweep = 0 }) {
  const a = audio();
  const t = a.currentTime + delay;
  const len = Math.max(1, Math.floor(a.sampleRate * dur));
  const buf = a.createBuffer(1, len, a.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
  const src = a.createBufferSource(); src.buffer = buf;
  const flt = a.createBiquadFilter();
  flt.type = 'bandpass'; flt.frequency.setValueAtTime(f, t); flt.Q.value = q;
  if (sweep) flt.frequency.exponentialRampToValueAtTime(Math.max(40, f + sweep), t + dur);
  const g = a.createGain();
  g.gain.setValueAtTime(vol, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  src.connect(flt); flt.connect(g); g.connect(master);
  src.start(t); src.stop(t + dur + 0.02);
}

